//! Team identity and the bundled `data/wvw-teams.json` table (ADR-010).
//!
//! The official API exposes team ids but not their names, so the names travel
//! inside the binary. A missing id is not an error: the UI falls back to the id.

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::Deserialize;

/// Table shipped with the addon, regenerated by `scripts/update_wvw_teams.ps1`.
pub const BUNDLED_JSON: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../data/wvw-teams.json"
));

/// One entry of the table.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
pub struct TeamEntry {
    pub id: u32,
    pub name: String,
    #[serde(default)]
    pub nation: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
struct File {
    #[serde(default)]
    teams: Vec<TeamEntry>,
}

/// Id -> name table for WvW teams.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct TeamTable {
    teams: HashMap<u32, TeamEntry>,
}

impl TeamTable {
    /// Parses the bundled table format. Unknown fields are ignored on purpose so
    /// the script can add metadata without breaking older builds.
    pub fn parse(json: &str) -> Result<Self, serde_json::Error> {
        let file: File = serde_json::from_str(json)?;
        let teams = file.teams.into_iter().map(|t| (t.id, t)).collect();
        Ok(Self { teams })
    }

    /// Name of the team, if known.
    pub fn name(&self, id: u32) -> Option<&str> {
        self.teams.get(&id).map(|t| t.name.as_str())
    }

    /// Region of the team as curated in the table (`EU`/`NA`), if known.
    pub fn nation(&self, id: u32) -> Option<&str> {
        self.teams.get(&id).map(|t| t.nation.as_str())
    }

    /// How the UI shows a team: `Name (id)`, or `(id)` when the name is unknown (RF-03a).
    pub fn label(&self, id: u32) -> String {
        match self.name(id) {
            Some(name) => format!("{name} ({id})"),
            None => format!("({id})"),
        }
    }

    /// Number of known teams.
    pub fn len(&self) -> usize {
        self.teams.len()
    }

    /// Whether the table is empty.
    pub fn is_empty(&self) -> bool {
        self.teams.is_empty()
    }
}

/// The bundled table, parsed once.
///
/// A broken JSON yields an empty table: showing ids beats crashing the game (RNF-06).
pub fn bundled() -> &'static TeamTable {
    static TABLE: OnceLock<TeamTable> = OnceLock::new();
    TABLE.get_or_init(|| TeamTable::parse(BUNDLED_JSON).unwrap_or_default())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rf03i_bundled_table_holds_every_live_team() {
        let table = bundled();
        assert_eq!(table.len(), 33, "15 NA + 18 EU as captured on 2026-10-31");
        assert_eq!(table.name(12014), Some("Great House Aviary"));
        assert_eq!(table.nation(12014), Some("EU"));
        assert_eq!(table.name(11001), Some("Moogooloo"));
        assert_eq!(table.name(999_999), None);
    }

    #[test]
    fn rf03a_label_falls_back_to_the_id_alone() {
        let table = bundled();
        assert_eq!(table.label(12014), "Great House Aviary (12014)");
        assert_eq!(table.label(12099), "(12099)");
    }

    #[test]
    fn rf03i_broken_table_degrades_to_ids() {
        assert!(TeamTable::parse("not json").is_err());
        let empty = TeamTable::parse(r#"{ "teams": [] }"#).unwrap();
        assert!(empty.is_empty());
        assert_eq!(empty.label(12014), "(12014)");
    }
}
